	[
		'slug'        => 'communal-area-cleaning-schedule',
		'title'       => 'Communal Area Cleaning: How Often and What’s Included',
		'seo_title'   => 'Communal Area Cleaning: How Often & What’s Included',
		'description' => 'Communal area cleaning explained: how often stairs, halls and entrances should be cleaned, what’s included, and a sample schedule for flats and HMOs.',
		'category'    => 'landlords',
		'service'     => 'communal-area-cleaning',
