		'slug'        => 'void-property-cleaning',
		'title'       => 'Void Property Cleaning: Turning Rentals Around Faster',
		'seo_title'   => 'Void Property Cleaning: Turn Rentals Around Faster',
		'description' => 'Void property cleaning for landlords: the right order for cleans, repairs and decorating, a full checklist, and ways to cut empty weeks between tenancies.',
		'category'    => 'landlords',
		'service'     => 'end-of-tenancy-cleaning',
		'related'     => [ 'landlord-inventory-cleaning-standards', 'communal-area-cleaning-schedule', 'student-house-move-out-cleaning-hull' ],
